CREATE DATABASE IF NOT EXISTS city_motors CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE city_motors;
CREATE TABLE IF NOT EXISTS admins(id INT AUTO_INCREMENT PRIMARY KEY,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS products(id INT AUTO_INCREMENT PRIMARY KEY,sku VARCHAR(60) NOT NULL UNIQUE,name VARCHAR(180) NOT NULL,category VARCHAR(100) NOT NULL,brand VARCHAR(100) DEFAULT NULL,standard_code VARCHAR(80) DEFAULT NULL,bore_mm DECIMAL(10,2) DEFAULT NULL,outer_mm DECIMAL(10,2) DEFAULT NULL,width_mm DECIMAL(10,2) DEFAULT NULL,material VARCHAR(120) DEFAULT NULL,price DECIMAL(12,2) NOT NULL DEFAULT 0,stock INT NOT NULL DEFAULT 0,image_url VARCHAR(500) DEFAULT NULL,description TEXT,active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(category),INDEX(name));
CREATE TABLE IF NOT EXISTS customers(id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,email VARCHAR(190) NOT NULL,phone VARCHAR(40),company VARCHAR(180),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS quotes(id BIGINT AUTO_INCREMENT PRIMARY KEY,quote_ref VARCHAR(40) NOT NULL UNIQUE,customer_name VARCHAR(150) NOT NULL,email VARCHAR(190) NOT NULL,phone VARCHAR(40),company VARCHAR(180),message TEXT,status ENUM('Nouveau','En étude','Envoyé','Accepté','Refusé') DEFAULT 'Nouveau',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS quote_items(id BIGINT AUTO_INCREMENT PRIMARY KEY,quote_id BIGINT NOT NULL,product_id INT NULL,sku VARCHAR(60) NOT NULL,product_name VARCHAR(180) NOT NULL,quantity INT NOT NULL,FOREIGN KEY(quote_id) REFERENCES quotes(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS orders(id BIGINT AUTO_INCREMENT PRIMARY KEY,order_ref VARCHAR(40) NOT NULL UNIQUE,customer_name VARCHAR(150) NOT NULL,email VARCHAR(190) NOT NULL,phone VARCHAR(40),company VARCHAR(180),address TEXT,status ENUM('Reçue','En préparation','Expédiée','Livrée','Annulée') DEFAULT 'Reçue',total DECIMAL(12,2) NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS order_items(id BIGINT AUTO_INCREMENT PRIMARY KEY,order_id BIGINT NOT NULL,product_id INT NULL,sku VARCHAR(60) NOT NULL,product_name VARCHAR(180) NOT NULL,unit_price DECIMAL(12,2) NOT NULL,quantity INT NOT NULL,FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE SET NULL);
